/* From Uiverse.io by KingHendrie  - Tags: simple, icon, animation, action, button, rounded, social media, button hover effect  */
.__UIV_SCOPE__ .send-checkbox {
  display: none;
}

.__UIV_SCOPE__ .send-button {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  padding: 10px 20px;
  border: 2px solid #ddd;
  border-radius: 15px;
  background-color: #f9f9f9;
  color: #2c2c2c;
  font-family: Arial, sans-serif;
  font-size: 16px;
  font-weight: 500;
  cursor: pointer;
  box-shadow: inset 2px 2px 5px rgba(0, 0, 0, 0.1),
    2px 2px 5px rgba(0, 0, 0, 0.1);
  transition: background-color 0.3s, box-shadow 0.3s, transform 0.3s;
  position: relative;
  overflow: hidden;
  white-space: nowrap;
}

.__UIV_SCOPE__ .send-checkbox:checked + .send-button .message {
  opacity: 0;
}

.__UIV_SCOPE__ .send-checkbox:checked + .send-button .message-sent {
  animation: fadeIn 3s forwards;
}

.__UIV_SCOPE__ .send-checkbox:checked + .send-button svg {
  animation: send 1s forwards;
}

@keyframes rotate-hover {
  0% {
    transform: rotate(0);
  }
  100% {
    transform: rotate(40deg);
  }
}

@keyframes send {
  0% {
    transform: translateX(0) rotate(40deg);
  }
  100% {
    transform: translateX(150px) rotate(40deg);
  }
}

@keyframes fadeIn {
  0% {
    opacity: 0;
  }
  100% {
    opacity: 1;
  }
}

.__UIV_SCOPE__ .send-button .message-sent {
  position: absolute;
  top: 50%;
  left: 50%;
  transform: translate(-50%, -50%);
  opacity: 0;
  color: #125b96;
}

.__UIV_SCOPE__ .send-button:hover {
  background-color: #e0e0e0;
  box-shadow: inset -2px -2px 5px rgba(0, 0, 0, 0.1),
    3px 3px 7px rgba(0, 0, 0, 0.15);
  transform: translateY(-2px);
}

.__UIV_SCOPE__ .send-button:hover svg {
  animation: rotate-hover 0.2s;
  transform: rotate(40deg);
}
